// Copies the homepage's section components into the package's organisms folder,
// rewriting imports and image paths so they render from the package.
// The Ask the Advisory dock is presentational in the package (no network), so only
// its module CSS is synced (the package appends an inline-host block).
import { readFileSync, writeFileSync, readdirSync, existsSync, rmSync } from 'node:fs';
import { resolve, dirname, basename } from 'node:path';
import { fileURLToPath } from 'node:url';

const here = dirname(fileURLToPath(import.meta.url));
const root = resolve(here, '../../..');
const src = resolve(root, 'artifacts/the-advisory/src/components');
const dst = resolve(here, '../src/react/organisms');

const IMAGE_KEYS = {
  'e9b8cdba-14b2-47a7-98fc-71398702bfb2.png': 'mastheadLogo',
  'f2056b34-3966-47a1-8a4b-abf1f59c0dc6.png': 'footerLogo',
  '986be0ce-7527-485f-93bd-b2c0e610393f.png': 'heroCityscape',
  '98ae5cd5-94a4-467c-b834-fed7a3d6f6b9.png': 'wealthTrustPhoto',
};

const DOCK_INLINE_BLOCK = `
/* ---- Inline (documentation) host ----------------------------------------
   Renders the dock in normal flow so it can be shown inside a docs page.
   Not used by The Advisory. */
.inlineHost { position: relative; display: flex; flex-direction: column; align-items: flex-end; gap: 16px; padding: 16px; background: var(--color-blue-50); }
.inlineHost .dockWrapper { position: static; height: auto; }
.inlineHost .dock { position: relative; bottom: auto; right: auto; max-width: 100%; height: 620px; animation: none; }
.inlineHost .triggerContainer { position: static; }
@media (max-width: 768px) {
  .inlineHost .dock { height: 560px; }
}
`;

const files = readdirSync(src);
const homepageNames = new Set(files.map((f) => f.replace(/\.module\.css$|\.tsx$/, '')));

// Remove organisms that no longer exist on the homepage.
for (const f of readdirSync(dst)) {
  const name = f.replace(/\.module\.css$|\.tsx$/, '');
  if (/\.(tsx|css)$/.test(f) && !['index', 'content'].includes(name) && !homepageNames.has(name)) {
    rmSync(resolve(dst, f));
    console.log('removed', f);
  }
}

for (const f of files) {
  const from = resolve(src, f);
  const to = resolve(dst, f);
  let text = readFileSync(from, 'utf8');
  if (f === 'AskTheAdvisoryDock.tsx') continue; // presentational copy maintained by hand
  if (f === 'AskTheAdvisoryDock.module.css') text += DOCK_INLINE_BLOCK;
  if (f.endsWith('.tsx')) {
    text = text.replace(/^'use client';\n\n?/, '');
    text = text.replace(/from '\.\.\/data\/aba'/g, "from '@workspace/aba-content'");
    text = text.replace(/from '\.\.\/data\/content'/g, "from './content'");
    text = text.replace(/NodeJS\.Timeout/g, 'ReturnType<typeof setTimeout>'); // package has no Node types
    let usesImage = false;
    text = text.replace(/src="\/images\/([^"]+)"/g, (_, file) => {
      const key = IMAGE_KEYS[file];
      if (!key) throw new Error(`Unknown image ${file} in ${f}; add it to IMAGE_KEYS and assets/images`);
      usesImage = true;
      return `src={image('${key}')}`;
    });
    if (usesImage) {
      text = `import { useAbaAssets } from '../assets';\n` + text;
      // Inject the hook at the top of the first exported function component.
      text = text.replace(/(export function \w+\([^)]*\)\s*{\n)/, `$1  const { image } = useAbaAssets();\n`);
    }
  }
  writeFileSync(to, text);
}

// Keep the package copy of the page copy in step with the homepage.
const contentFrom = resolve(root, 'artifacts/the-advisory/src/data/content.ts');
if (existsSync(contentFrom)) writeFileSync(resolve(dst, 'content.ts'), readFileSync(contentFrom, 'utf8'));

// Regenerate the barrel.
const names = [...new Set(readdirSync(dst).filter((f) => f.endsWith('.tsx')).map((f) => basename(f, '.tsx')))].sort();
writeFileSync(
  resolve(dst, 'index.ts'),
  `// Generated by scripts/sync-organisms.mjs — do not edit by hand.\n` + names.map((n) => `export * from './${n}';\n`).join('') + `export { content as homepageContent } from './content';\n`,
);
console.log('synced', names.join(', '));
